int nvkm_i2c_aux_ctor ( const struct nvkm_i2c_aux_func * func , struct nvkm_i2c_pad * pad , int id , struct nvkm_i2c_aux * aux ) { struct nvkm_device * device = pad -> i2c -> subdev . device ; aux -> func = func ; aux -> pad = pad ; aux -> id = id ; list_add_tail ( & aux -> head , & pad -> i2c -> aux ) ; AUX_TRACE ( aux , "ctor" ) ; snprintf ( aux -> i2c . name , sizeof ( aux -> i2c . name ) , "nvkm-%s-aux-%04x" , dev_name ( device -> dev ) , id ) ; aux -> i2c . owner = THIS_MODULE ; aux -> i2c . dev . parent = device -> dev ; aux -> i2c . algo = & nvkm_i2c_aux_i2c_algo ; return i2c_add_adapter ( & aux -> i2c ) ; } 